const D = { energy: .6, scale: 1, speed: 1, density: .5, dilate: .5, hue: 36, x: .5, y: .5, style: 'chains', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Granular media failing under biaxial compression. Two real pieces of physics:
//  1. FORCE CHAINS via the q-model (Liu et al.): each grain hands its load down to the two
//     grains beneath it in random fractions. A handful of chains end up carrying almost all
//     of the load — the famous heterogeneous force network, emergent, not painted on.
//  2. SHEAR BANDS: strain refuses to stay uniform and localizes into narrow inclined seams
//     where grains ride over each other and the packing DILATES. Loose grains cannot carry
//     load, so the chains route AROUND the band and it unloads — which is exactly what the
//     band looks like in the lab: a dark seam cutting a bright network.
// Perpetual: bands nucleate, take over, and fade on staggered lives while the load axis turns.
const u = Math.min(width, height);
const sd = P.seed | 0;
function hsh(ix, iy, iz) {
  let h = (Math.imul(ix | 0, 374761393) + Math.imul(iy | 0, 668265263) + Math.imul(iz | 0, 1274126177) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); };
const tt = K.t, style = P.style;
const dr1 = Math.sin(tt * 0.061), dr2 = Math.sin(tt * 0.143 + 1.7), dr3 = Math.sin(tt * 0.229 + 0.4);
const zoom = Math.max(1, P.scale);

// ---- the assembly ----
const nx = Math.max(10, Math.round((16 + P.density * 26) * zoom * 0.5 + (16 + P.density * 26) * 0.5));
const cw = width / nx;
const rowH = cw * 0.866;
const ny = Math.max(6, Math.ceil(height / rowH) + 2);
const NG = nx * ny;
if (!S.W || S.ng !== NG) { S.W = new Float32Array(NG); S.QX = new Float32Array(NG); S.QY = new Float32Array(NG); S.DL = new Float32Array(NG); S.ng = NG; }
const W = S.W, QX = S.QX, QY = S.QY, DL = S.DL;

// ---- shear bands on staggered lives: one is always taking over as another dies ----
if (!S.bands || S.seedUsed !== P.seed || S.lastT == null || tt < S.lastT - 0.5) {
  S.seedUsed = P.seed; S.bands = []; S.next = tt; S.ctr = 0;
}
S.lastT = tt;
const BLIFE = 34 / Math.max(0.2, P.speed);
while (S.next <= tt && S.bands.length < 5) {
  const c = S.ctr++;
  // conjugate Coulomb geometry: bands come in at roughly +/-(45 + phi/2) to the major stress
  const conj = (c % 2 ? 1 : -1);
  S.bands.push({
    t0: S.next, c: c,
    ang: conj * (0.95 + 0.30 * fr(c * 13 + 1)) + (fr(c * 13 + 2) - 0.5) * 0.25,
    off: (fr(c * 13 + 3) - 0.5) * u * 0.75,
    w: u * (0.030 + 0.030 * fr(c * 13 + 4)),
    slip: u * (0.020 + 0.030 * fr(c * 13 + 5))
  });
  S.next += (BLIFE * 0.42) * (0.7 + 0.6 * fr(c * 13 + 6));
}
S.bands = S.bands.filter(b => tt - b.t0 < BLIFE);
if (S.next > tt + BLIFE) S.next = tt;

// The load: compression accumulates and relaxes on three incommensurate rates, so the sample
// is always visibly working. Peak strain lands near 10%, which is where a real granular test
// fails — and it is also what keeps this off the STATIC gate.
const eps = (0.030 + 0.055 * (0.5 + 0.5 * Math.sin(tt * 0.037 * P.speed))
          + 0.028 * Math.sin(tt * 0.083 * P.speed + 1.3)
          + 0.014 * Math.sin(tt * 0.151 * P.speed + 0.4)) * (0.4 + P.energy);
const axis = tt * 0.009 * P.speed + Math.sin(tt * 0.015) * 0.35;   // the major stress axis turns
// Cyclic simple shear — the classic way a granular sample is actually worked. Rows slide over
// one another on three incommensurate rates, so every grain in the frame is always moving.
// Kept under ~0.35 cell of relative offset per row so vertical adjacency (and therefore the
// q-model's contact topology) still holds.
const shr = cw * 0.55 * (Math.sin(tt * 0.043 * P.speed) + 0.5 * Math.sin(tt * 0.091 * P.speed + 1.1)
          + 0.3 * Math.sin(tt * 0.017 * P.speed + 2.3)) * (0.35 + P.energy * 0.65);

// ---- deform the reference lattice: uniform compression + each band's slip and dilation ----
const cx0 = width * 0.5, cy0 = height * 0.5;
for (let j = 0; j < ny; j++) {
  for (let i = 0; i < nx; i++) {
    const p = j * nx + i;
    let rx = (i + (j & 1 ? 0.5 : 0)) * cw + (hsh(i, j, 3) - 0.5) * cw * 0.30;
    let ry = j * rowH - rowH + (hsh(i, j, 5) - 0.5) * cw * 0.30;
    // biaxial: squeezed vertically, spreading horizontally (Poisson + dilatancy)
    let dx = (rx - cx0) * eps * 0.55, dy = -(ry - cy0) * eps;
    dx += (j - ny * 0.5) * shr * 0.35;                     // + the cyclic simple shear
    let dil = 0;
    for (const b of S.bands) {
      const age = tt - b.t0;
      if (age < 0) continue;
      // the band fades in and out — a band never appears or vanishes in a single frame
      const fin = Math.min(1, age / 5.0);
      const fout = Math.min(1, Math.max(0, (BLIFE - age) / (BLIFE * 0.45)));
      const amp = fin * fout;
      if (amp < 0.01) continue;
      const sa = Math.sin(b.ang + axis), ca = Math.cos(b.ang + axis);
      const d = (rx - cx0) * sa - (ry - cy0) * ca - b.off;    // signed distance to the band
      const th = Math.tanh(d / b.w);
      const sech2 = 1 - th * th;
      // slip: material either side of the band slides in opposite directions
      const sl = b.slip * th * amp * (0.4 + eps * 22);
      dx += ca * sl; dy += sa * sl;
      // dilation: the band swells normal to itself as grains climb over each other
      const dd = b.w * 0.55 * sech2 * amp * P.dilate * (0.4 + eps * 22);
      dx += sa * dd * Math.sign(d || 1); dy += -ca * dd * Math.sign(d || 1);
      dil += sech2 * amp;
    }
    QX[p] = rx + dx; QY[p] = ry + dy;
    DL[p] = Math.min(1, dil * P.dilate * 1.15);
    W[p] = 0;
  }
}

// ---- q-model sweep: hand the platen load down the packing, grain to grain ----
for (let i = 0; i < nx; i++) W[i] = 1;
for (let j = 0; j < ny - 1; j++) {
  for (let i = 0; i < nx; i++) {
    const p = j * nx + i;
    const w = W[p] + 0.06;                     // + self weight
    // the two grains it rests on in a hex packing
    let iL = (j & 1) ? i : i - 1, iR = (j & 1) ? i + 1 : i;
    iL = ((iL % nx) + nx) % nx; iR = ((iR % nx) + nx) % nx;
    const pL = (j + 1) * nx + iL, pR = (j + 1) * nx + iR;
    // the split is disordered (this is what makes chains) and drifts slowly so the network
    // reorganises smoothly instead of flickering
    let q = 0.5 + (hsh(i, j, 7) - 0.5) * 1.5
          + 0.38 * Math.sin(tt * (0.055 + hsh(i, j, 9) * 0.085) * P.speed + hsh(i, j, 11) * 6.28);
    // geometry: load leans toward whichever support actually sits under it
    q += (QX[p] - QX[pL]) < (QX[pR] - QX[p]) ? 0.16 : -0.16;
    // loose grains cannot carry load, so the chains route AROUND a dilated band. Emergent.
    const aL = 1 - DL[pL] * 0.92, aR = 1 - DL[pR] * 0.92;
    q = Math.max(0.02, Math.min(0.98, q));
    const wl = q * aL, wr = (1 - q) * aR;
    const s = wl + wr;
    const fL = s > 1e-6 ? wl / s : 0.5, fR = s > 1e-6 ? wr / s : 0.5;
    // the band sheds load overall — that is why it reads dark
    const pass = 1 - DL[p] * 0.55;
    W[pL] += w * fL * pass; W[pR] += w * fR * pass;
  }
}
// normalise so the palette is stable however tall the pile is
let wmax = 1e-6;
for (let p = 0; p < NG; p++) if (W[p] > wmax) wmax = W[p];
const inv = 1 / wmax;

// ---- render ----
const ctx = drawingContext;
const aa = Math.max(0, Math.min(100, P.alpha)) / 100;
const hb = ((P.hue % 360) + 360) % 360, hh = hb / 360;
const gr = cw * 0.47;
const gain = 0.45 + P.energy * 0.9;
push();
// the void the assembly sits in — never pure black
if (style === 'plate') { ctx.fillStyle = 'rgba(170,165,154,' + aa.toFixed(3) + ')'; }   // toned drafting card, not white paper
else if (style === 'xray') { ctx.fillStyle = 'rgba(16,18,22,' + aa.toFixed(3) + ')'; }
else { ctx.fillStyle = 'rgba(14,13,16,' + aa.toFixed(3) + ')'; }
ctx.fillRect(0, 0, width, height);

// --- grains, batched into force buckets: one fill per bucket, not one per grain ---
const NB = 7;
if (style !== 'plate') {
  for (let b = 0; b < NB; b++) {
    ctx.beginPath();
    let any = false;
    for (let p = 0; p < NG; p++) {
      const f = Math.min(1, Math.pow(W[p] * inv, 0.42));
      if (Math.min(NB - 1, Math.floor(f * NB)) !== b) continue;
      const x = QX[p], y = QY[p];
      if (x < -gr || x > width + gr || y < -gr || y > height + gr) continue;
      const rr = gr * (0.72 + 0.28 * hsh(p, 1, 13)) * (1 + DL[p] * 0.10);
      ctx.moveTo(x + rr, y); ctx.arc(x, y, rr, 0, 6.2831); any = true;
    }
    if (!any) continue;
    const f = (b + 0.5) / NB;
    let r, g2, b2;
    if (style === 'dem') {                       // false-colour by load: the DEM figure
      r = Math.min(1, Math.max(0, f * 3.0 - 0.9));
      g2 = Math.min(1, Math.max(0, f < 0.5 ? f * 2.0 : 2.0 - f * 2.0) + Math.max(0, f * 1.5 - 1.0));
      b2 = Math.min(1, Math.max(0, 1.0 - f * 2.6));
      r = r * 0.92 + 0.06; g2 = g2 * 0.92 + 0.07; b2 = b2 * 0.92 + 0.10;
    } else if (style === 'xray') {               // CT slice: dense packing bright, the dilated band dark
      const v = 0.30 + 0.42 * (1 - f * 0.25);
      r = v * 0.95; g2 = v * 0.97; b2 = v;
    } else if (style === 'grains') {             // actual sand: warm mineral colour, lit by load
      const tone = 0.34 + f * 0.38;
      r = tone * (0.98 + 0.16 * Math.cos(6.2831 * hh));
      g2 = tone * (0.84 + 0.12 * Math.cos(6.2831 * (hh + 0.05)));
      b2 = tone * (0.66 + 0.08 * Math.cos(6.2831 * (hh + 0.12)));
    } else {                                     // chains (default): grains dim, network bright
      const v = 0.15 + f * 0.30;
      r = v * 0.9; g2 = v * 0.92; b2 = v * 1.0;
    }
    ctx.fillStyle = 'rgba(' + Math.round(Math.min(255, r * 255)) + ',' + Math.round(Math.min(255, g2 * 255)) + ',' + Math.round(Math.min(255, b2 * 255)) + ',' + aa.toFixed(3) + ')';
    ctx.fill();
  }
} else {
  // plate: every grain is an outline, so the diagram is a real contact graph — nodes and
  // edges — rather than a few lines floating on empty paper
  ctx.beginPath();
  for (let p = 0; p < NG; p++) {
    const x = QX[p], y = QY[p];
    if (x < -gr || x > width + gr || y < -gr || y > height + gr) continue;
    const rr = gr * (0.72 + 0.28 * hsh(p, 1, 13)) * (1 + DL[p] * 0.10);
    ctx.moveTo(x + rr, y); ctx.arc(x, y, rr, 0, 6.2831);
  }
  ctx.strokeStyle = 'rgba(46,44,40,' + (aa * 0.55).toFixed(3) + ')';
  ctx.lineWidth = Math.max(0.5, gr * 0.055); ctx.stroke();
}

// --- the force network: one stroke per width bucket ---
const CB = 6;
for (let b = 0; b < CB; b++) {
  ctx.beginPath();
  let any = false;
  for (let j = 0; j < ny - 1; j++) {
    for (let i = 0; i < nx; i++) {
      const p = j * nx + i;
      const f = Math.min(1, Math.pow(W[p] * inv, 0.42));
      if (Math.min(CB - 1, Math.floor(f * CB)) !== b) continue;
      if (f < 0.16) continue;                        // only chains that actually carry load
      let iL = (j & 1) ? i : i - 1, iR = (j & 1) ? i + 1 : i;
      iL = ((iL % nx) + nx) % nx; iR = ((iR % nx) + nx) % nx;
      const pL = (j + 1) * nx + iL, pR = (j + 1) * nx + iR;
      for (const q of [pL, pR]) {
        if (Math.abs(QX[q] - QX[p]) > cw * 2.2) continue;   // do not draw across the wrap seam
        ctx.moveTo(QX[p], QY[p]); ctx.lineTo(QX[q], QY[q]); any = true;
      }
    }
  }
  if (!any) continue;
  const f = (b + 0.5) / CB;
  let col, lw = Math.max(0.5, gr * 0.30 * f * (0.5 + P.energy * 1.1));
  if (style === 'plate') { col = 'rgba(28,30,38,' + (aa * (0.15 + f * 0.7)).toFixed(3) + ')'; lw = Math.max(0.4, gr * 0.16 * f); }
  else if (style === 'xray') col = 'rgba(250,250,255,' + (aa * f * 0.28).toFixed(3) + ')';
  else if (style === 'dem') col = 'rgba(255,250,240,' + (aa * f * 0.42).toFixed(3) + ')';
  else if (style === 'grains') col = 'rgba(255,238,206,' + (aa * f * 0.40).toFixed(3) + ')';
  else {
    // chains: hot where the load concentrates — this is the image everyone knows
    const r = Math.min(255, 90 + 165 * f), g2 = Math.min(255, 60 + 170 * f * f), b2 = Math.min(255, 110 + 90 * (1 - f));
    col = 'rgba(' + (r | 0) + ',' + (g2 | 0) + ',' + (b2 | 0) + ',' + (aa * (0.20 + f * 0.72) * gain).toFixed(3) + ')';
  }
  ctx.strokeStyle = col; ctx.lineWidth = lw; ctx.lineCap = 'round'; ctx.stroke();
}
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
